// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 1, depositAmount);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();
        uint256 balanceBefore = c.balances(caller);
        vm.assume(balanceBefore >= c.MinSum() && balanceBefore >= collectAmount);
        vm.prank(caller);
        c.Collect(collectAmount);
        uint256 balanceAfter = c.balances(caller);
        assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance should decrease by collectAmount");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(); 
    }

    function testFuzz_property(address sender, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to avoid reverts due to underflow/overflow
        depositAmount = bound(depositAmount, 0, type(uint128).max);
        collectAmount = bound(collectAmount, 0, depositAmount);

        // Ensure MinSum is set to 0 so any positive balance can collect
        c.SetMinSum(0);
        c.Initialized();

        // Fund the sender and deposit
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        // Record total balance before collect
        uint256 totalBefore = address(c).balance;

        // Call Collect (may revert if conditions not met, but we set conditions so it won't)
        vm.prank(sender);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Only assert if the call succeeded (otherwise no change expected)
        if (success) {
            uint256 totalAfter = address(c).balance;
            // The invariant: total ether in contract should decrease by exactly collectAmount (since sent to sender)
            // In reference: balances[sender] decreases by collectAmount, so total decreases.
            // In mutant: balances[sender] increases, so total increases by collectAmount (ether sent out but balance increased).
            // So the rule is: totalAfter == totalBefore - collectAmount
            assertTrue(totalAfter == totalBefore - collectAmount, "Total balance should decrease by collectAmount");
        }
    }
}

