pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(sender != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max / 2);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);

        // Ensure MinSum is low enough
        if (c.MinSum() > depositAmount) {
            c.SetMinSum(0);
        }
        c.Initialized();

        // Deposit
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(sender);

        // Collect
        vm.prank(sender);
        c.Collect(collectAmount);

        uint256 balanceAfter = c.balances(sender);

        // In the reference, balanceBefore - collectAmount == balanceAfter
        assertTrue(balanceAfter == balanceBefore - collectAmount);
    }
}

