pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 am, uint256 preBalance) public {
        // Bound preBalance to a reasonable range
        preBalance = bound(preBalance, 1 ether, 1000 ether);
        am = bound(am, 0, preBalance);

        // Setup: give caller some balance via deposit
        vm.deal(caller, preBalance);
        vm.prank(caller);
        c.Deposit{value: preBalance}();

        // Record total balance before Collect
        uint256 totalBefore = address(c).balance;

        // Call Collect
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        // If Collect succeeded, total ether held by contract should decrease by am (since caller receives am)
        if (success) {
            uint256 totalAfter = address(c).balance;
            assertTrue(totalAfter == totalBefore - am, "Total ether in contract decreased by am");
        } else {
            // If it reverted, total should be unchanged
            uint256 totalAfter = address(c).balance;
            assertTrue(totalAfter == totalBefore, "Total ether unchanged on revert");
        }
    }
}

