pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount, uint256 minSum) public {
        // Restrict inputs to avoid reverts: amount must be nonzero and sender must have enough ETH to deposit
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.assume(sender != address(0));

        // Initialize the contract (required before any Collect)
        c.Initialized();
        // Set MinSum to a value that allows Collect for the caller
        c.SetMinSum(minSum);

        // Deposit some funds as the caller
        vm.deal(sender, amount);
        vm.prank(sender);
        c.Deposit{value: amount}();

        // Record total balances before Collect
        uint256 totalBefore = 0;
        // We can't iterate over all addresses, but we can check the caller's balance before and after
        uint256 callerBalanceBefore = c.balances(sender);

        // Ensure the caller can collect (balance >= minSum and balance >= _am)
        // We set amount = _am to be exactly the deposited amount, so condition holds
        uint256 collectAm = amount;
        vm.assume(callerBalanceBefore >= minSum && callerBalanceBefore >= collectAm);

        // Call Collect
        vm.prank(sender);
        c.Collect(collectAm);

        // Check caller's balance after
        uint256 callerBalanceAfter = c.balances(sender);

        // The invariant: caller's balance should not increase after Collect
        // In reference, callerBalanceAfter = callerBalanceBefore - collectAm (decrease)
        // In buggy, callerBalanceAfter = callerBalanceBefore + collectAm (increase)
        // So assert that callerBalanceAfter <= callerBalanceBefore
        assertTrue(callerBalanceAfter <= callerBalanceBefore);
    }
}

