pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x1234);
    address bob = address(0x5678);

    function setUp() public {
        c = new C();
        c.Initialized();
        vm.deal(alice, 10 ether);
        vm.deal(bob, 10 ether);
    }

    function testFuzz_property(uint256 _am, uint256 depositAlice, uint256 depositBob) public {
        // Bound inputs to reasonable ranges
        _am = bound(_am, 0, 5 ether);
        depositAlice = bound(depositAlice, 0, 5 ether);
        depositBob = bound(depositBob, 0, 5 ether);

        // Set MinSum to 1 ether so reference has a condition
        if (c.MinSum() != 1 ether) c.SetMinSum(1 ether);

        // Alice and Bob deposit
        vm.prank(alice);
        c.Deposit{value: depositAlice}();
        vm.prank(bob);
        c.Deposit{value: depositBob}();

        uint256 aliceBefore = c.balances(alice);
        uint256 bobBefore = c.balances(bob);

        // Alice calls Collect
        vm.prank(alice);
        c.Collect(_am);

        uint256 aliceAfter = c.balances(alice);
        uint256 bobAfter = c.balances(bob);

        // General rule: for any non-caller (bob), balance unchanged
        // For caller (alice), balance either unchanged (if condition failed) or decreased by exactly _am
        assertTrue(bobAfter == bobBefore, "Non-caller balance changed");
        assertTrue(aliceAfter == aliceBefore || aliceAfter == aliceBefore - _am, "Caller balance neither unchanged nor decreased by _am");
    }
}

