pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to avoid overflow issues
        minSum = bound(minSum, 0, 1e24);
        depositAmount = bound(depositAmount, 0, 1e24);
        collectAmount = bound(collectAmount, 0, 1e24);

        // Initialize the contract: set MinSum and lock it
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit funds into the caller's account
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);

        // Attempt Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        uint256 balanceAfter = c.balances(caller);

        // General rule: 
        // If Collect reverted, then either balanceBefore < minSum or balanceBefore < collectAmount
        // If Collect succeeded, then balanceBefore >= minSum and balanceBefore >= collectAmount and balanceAfter == balanceBefore - collectAmount
        bool reverted = !success;
        bool rule = true;

        if (reverted) {
            // Must have been because of minSum or amount condition
            rule = (balanceBefore < minSum || balanceBefore < collectAmount);
        } else {
            // Must have succeeded only when balance >= minSum and balance >= collectAmount
            rule = (balanceBefore >= minSum && balanceBefore >= collectAmount && balanceAfter == balanceBefore - collectAmount);
        }

        assertTrue(rule);
    }
}

