pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 minSum, uint256 withdrawAmount) public {
        vm.assume(caller != address(0));
        vm.assume(initialBalance > 0.1 ether);
        minSum = bound(minSum, 0.1 ether, initialBalance / 2);
        withdrawAmount = bound(withdrawAmount, 0.1 ether, minSum);

        c.SetMinSum(minSum);
        c.Initialized();

        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        uint256 balanceBefore = c.balances(caller);
        require(balanceBefore >= minSum, "Precondition failed: balance < MinSum");

        try c.Collect(withdrawAmount) {
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter <= balanceBefore, "Balance increased after Collect");
            assertTrue(balanceAfter == balanceBefore - withdrawAmount, "Balance did not decrease by withdrawAmount");
        } catch {
            revert("Collect reverted unexpectedly");
        }
    }
}

