pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAmount, address randomAddr) public {
        // Bound inputs to reasonable values
        depositAmount = bound(depositAmount, 0, 1000 ether);
        withdrawAmount = bound(withdrawAmount, 0, 1000 ether);

        // Ensure caller is not zero address
        vm.assume(caller != address(0));

        // Set MinSum to 0 to make Collect accessible
        c.SetMinSum(0);
        c.Initialized();

        // Give caller some ether
        vm.deal(caller, depositAmount);

        // Deposit into the contract
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record total balances sum before Collect
        uint256 totalBalBefore = c.balances(caller) + c.balances(randomAddr);
        uint256 contractEthBefore = address(c).balance;

        // Perform Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));

        // Record total balances sum after Collect
        uint256 totalBalAfter = c.balances(caller) + c.balances(randomAddr);
        uint256 contractEthAfter = address(c).balance;

        // For the reference contract (P), total balances should equal contract balance
        // This holds if withdrawAmount <= balances[caller] (due to the check)
        // For the buggy contract (M), the check is missing, so totalBalAfter can be less than contractEthAfter
        assertTrue(totalBalAfter == contractEthAfter);
    }
}

