pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount, address other) public {
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max / 2);
        vm.assume(collectAmount > 0);
        vm.assume(other != address(0) && other != caller);

        // Set MinSum to 0 so Collect can execute
        c.SetMinSum(0);
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 preBalance = c.balances(caller);
        uint256 preContractBalance = address(c).balance;
        uint256 preOtherBalance = c.balances(other);

        // Attempt Collect
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {}
        catch { reverted = true; }

        uint256 postBalance = c.balances(caller);
        uint256 postContractBalance = address(c).balance;
        uint256 postOtherBalance = c.balances(other);

        if (!reverted) {
            // After successful Collect, caller's balance must be preBalance - collectAmount
            assertTrue(postBalance == preBalance - collectAmount);
            // The contract balance decreases by exactly collectAmount
            assertTrue(postContractBalance == preContractBalance - collectAmount);
        } else {
            // If reverted, all balances must stay the same
            assertTrue(postBalance == preBalance);
            assertTrue(postOtherBalance == preOtherBalance);
            assertTrue(postContractBalance == preContractBalance);
        }
    }
}

