pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 deposit, uint256 withdraw, address other) public {
        vm.assume(caller != address(0) && other != address(0) && caller != other);
        vm.assume(deposit <= type(uint256).max - 1 ether); // avoid overflow in balance?
        // Initialize the contract
        c.SetMinSum(0); // allow any sum to collect
        c.Initialized();
        // Fund the caller
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();
        // Record pre-collect balance
        uint256 preBal = c.balances(caller);
        // Attempt collect
        vm.prank(caller);
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", withdraw));
        // Read post-collect balance
        uint256 postBal = c.balances(caller);
        // Rule: If the call succeeded (no revert), then preBal >= withdraw and postBal <= preBal
        // If it reverted, we skip because no state change
        if (success) {
            assertTrue(preBal >= withdraw && postBal <= preBal, "Balance increased or underflow");
        } else {
            // If revert, the balance should be unchanged
            assertTrue(postBal == preBal, "Revert should not change balance");
        }
    }
}

