pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 am, uint256 initialBalance, uint256 msgValue) public {
        // Bound inputs to reasonable ranges
        am = bound(am, 0, 1e18);
        initialBalance = bound(initialBalance, 0, 1e18);
        msgValue = bound(msgValue, 0, 1e18);

        // Ensure caller has enough ETH and balance
        vm.assume(caller != address(0));
        vm.deal(caller, initialBalance + msgValue);

        // Set MinSum to 0 to allow Collect for any non-zero balance
        vm.prank(caller);
        c.SetMinSum(0);
        c.Initialized();

        // Deposit to set initial balance
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // Record initial caller balance mapping
        uint256 initialCallerBalance = c.balances(caller);
        uint256 initialContractBalance = address(c).balance;

        // Call Collect(am)
        vm.prank(caller);
        (bool success, ) = address(c).call{value: msgValue}(abi.encodeWithSignature("Collect(uint256)", am));

        // Get post-state caller balance
        uint256 postCallerBalance = c.balances(caller);
        uint256 postContractBalance = address(c).balance;

        // If Collect succeeded, the caller's balance decreased by am, and contract balance decreased by am (plus msg.value stays)
        if (success) {
            // The caller's balance mapping entry changed
            assertTrue(postCallerBalance == initialCallerBalance - am, "Caller balance not decremented by am");
            // Contract balance decreased by am (the sent value) but msg.value added, so net change = msg.value - am
            assertTrue(postContractBalance == initialContractBalance + msgValue - am, "Contract balance mismatch");
        }
    }
}

