pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 deposit, uint256 minSum, uint256 amount) public {
        // Restrict deposit and amount to avoid overflow, and ensure minSum is set appropriately
        vm.assume(deposit > 0 && deposit <= type(uint256).max / 2);
        vm.assume(amount > 0 && amount <= deposit);
        vm.assume(minSum > 0 && minSum <= deposit);

        // Initialize the contract with minSum
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund the caller and deposit into the contract
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Perform Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));

        // The rule: after a successful Collect, the caller's balance in C must decrease by exactly amount
        if (success) {
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter == balanceBefore - amount, "Balance should decrease by amount");
        } else {
            // If revert, no state change expected
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter == balanceBefore, "Balance should remain unchanged on revert");
        }
    }
}
